/// <summary>
/// PaffH 09.09.23
/// exclude Field NDXModelNumber from overwrite, when using a template
/// </summary>
/// <param name = "_tableId">TableId</param>
/// <param name = "_fieldId">FieldId</param>
/// <returns>boolean</returns>
protected boolean shouldFieldBeCopied(TableId _tableId, FieldId _fieldId)
{
    boolean retValue = next shouldFieldBeCopied(_tableId, _fieldId);

    if (excludeFields && !excludeFields.in(fieldStr(InventTable, NDXModelNumber)))
    {
        excludeFields.add(fieldStr(InventTable, NDXModelNumber));
    }
    return retValue;
}
